    65	    let is_subtract = opcode & (1 << 9) != 0;
    66	    let operand = if is_immediate { operand_field } else { cpu.registers[operand_field as usize] };
    67	    let source = cpu.registers[low_register(opcode, 3)];
    68	    let result = if is_subtract { alu::subtract(source, operand) } else { alu::add(source, operand) };
    69	    cpu.registers[low_register(opcode, 0)] = result.value;
    70	    cpu.set_arithmetic_flags(result);
    71	    0
    72	}
