    74	/// THUMB.3: MOV/CMP/ADD/SUB Rd,#imm8.
    75	fn immediate_operation(cpu: &mut Cpu, opcode: u32) -> u32 {
    76	    let destination = low_register(opcode, 8);
    77	    let immediate = opcode & 0xFF;
    78	    let current = cpu.registers[destination];
    79	    match (opcode >> 11) & 3 {
    80	        0 => {
    81	            cpu.registers[destination] = immediate;
    82	            cpu.set_negative_and_zero(immediate);
    83	        }
    84	        1 => cpu.set_arithmetic_flags(alu::subtract(current, immediate)),
    85	        2 => {
    86	            let result = alu::add(current, immediate);
    87	            cpu.registers[destination] = result.value;
    88	            cpu.set_arithmetic_flags(result);
    89	        }
    90	        _ => {
    91	            let result = alu::subtract(current, immediate);
    92	            cpu.registers[destination] = result.value;
    93	            cpu.set_arithmetic_flags(result);
    94	        }
    95	    }
    96	    0
    97	}
