   191	/// PC as a base for PC-relative addressing: ($+4) AND NOT 2.
   192	fn word_aligned_pc(cpu: &Cpu) -> u32 {
   193	    cpu.registers[PROGRAM_COUNTER] & !3
   194	}
   195	
   196	/// THUMB.6: LDR Rd,[PC,#imm8*4].
   197	fn load_pc_relative(cpu: &mut Cpu, bus: &mut Bus, opcode: u32) -> u32 {
   198	    let address = word_aligned_pc(cpu).wrapping_add((opcode & 0xFF) << 2);
   199	    cpu.registers[low_register(opcode, 8)] = bus.read32(address);
   200	    1
   201	}
   202	
   203	/// Word load with the misaligned rotation (gbatek: ARM CPU Memory Alignments, "rotated read").
   204	fn load_word_rotated(bus: &mut Bus, address: u32) -> u32 {
   205	    bus.read32(address).rotate_right((address & 3) * 8)
   206	}
   207	
   208	/// LDRH; an odd address reads the aligned halfword rotated by 8 (ARMv4 behaviour).
   209	fn load_halfword_unsigned(bus: &mut Bus, address: u32) -> u32 {
   210	    (bus.read16(address) as u32).rotate_right((address & 1) * 8)
   211	}
   212	
   213	/// LDSH; an odd address acts as LDSB on that byte (ARMv4 behaviour).
   214	fn load_halfword_signed(bus: &mut Bus, address: u32) -> u32 {
   215	    if address & 1 != 0 {
   216	        load_byte_signed(bus, address)
   217	    } else {
   218	        bus.read16(address) as i16 as i32 as u32
   219	    }
   220	}
   221	
   222	fn load_byte_signed(bus: &mut Bus, address: u32) -> u32 {
   223	    bus.read8(address) as i8 as i32 as u32
   224	}
