   226	/// The data sizes of THUMB.7 to THUMB.11, decoded per format.
   227	#[derive(Clone, Copy)]
   228	enum Transfer {
   229	    StoreWord,
   230	    StoreHalfword,
   231	    StoreByte,
   232	    LoadWord,
   233	    LoadHalfword,
   234	    LoadByte,
   235	    LoadSignedHalfword,
   236	    LoadSignedByte,
   237	}
   238	
   239	/// Perform a single load or store of register Rd at `address`; returns internal cycles
   240	/// (1I for loads, none for stores).
   241	fn transfer_single(cpu: &mut Cpu, bus: &mut Bus, transfer: Transfer, register: usize, address: u32) -> u32 {
   242	    let value = cpu.registers[register];
   243	    match transfer {
   244	        Transfer::StoreWord => bus.write32(address & !3, value),
   245	        Transfer::StoreHalfword => bus.write16(address & !1, value as u16),
   246	        Transfer::StoreByte => bus.write8(address, value as u8),
   247	        Transfer::LoadWord => cpu.registers[register] = load_word_rotated(bus, address),
   248	        Transfer::LoadHalfword => cpu.registers[register] = load_halfword_unsigned(bus, address),
   249	        Transfer::LoadByte => cpu.registers[register] = bus.read8(address) as u32,
   250	        Transfer::LoadSignedHalfword => cpu.registers[register] = load_halfword_signed(bus, address),
   251	        Transfer::LoadSignedByte => cpu.registers[register] = load_byte_signed(bus, address),
   252	    }
   253	    match transfer {
   254	        Transfer::StoreWord | Transfer::StoreHalfword | Transfer::StoreByte => 0,
   255	        _ => 1, // loads spend 1I
   256	    }
   257	}
