   259	/// Rb + Ro for THUMB.7 and THUMB.8.
   260	fn register_offset_address(cpu: &Cpu, opcode: u32) -> u32 {
   261	    cpu.registers[low_register(opcode, 3)].wrapping_add(cpu.registers[low_register(opcode, 6)])
   262	}
   263	
   264	/// THUMB.7: STR/STRB/LDR/LDRB Rd,[Rb,Ro].
   265	fn load_store_register_offset(cpu: &mut Cpu, bus: &mut Bus, opcode: u32) -> u32 {
   266	    let transfer = [Transfer::StoreWord, Transfer::StoreByte, Transfer::LoadWord, Transfer::LoadByte]
   267	        [((opcode >> 10) & 3) as usize];
   268	    let address = register_offset_address(cpu, opcode);
   269	    transfer_single(cpu, bus, transfer, low_register(opcode, 0), address)
   270	}
   271	
   272	/// THUMB.8: STRH/LDSB/LDRH/LDSH Rd,[Rb,Ro].
   273	fn load_store_sign_extended(cpu: &mut Cpu, bus: &mut Bus, opcode: u32) -> u32 {
   274	    let transfer = [
   275	        Transfer::StoreHalfword,
   276	        Transfer::LoadSignedByte,
   277	        Transfer::LoadHalfword,
   278	        Transfer::LoadSignedHalfword,
   279	    ][((opcode >> 10) & 3) as usize];
   280	    let address = register_offset_address(cpu, opcode);
   281	    transfer_single(cpu, bus, transfer, low_register(opcode, 0), address)
   282	}
   283	
   284	/// THUMB.9: STR/LDR Rd,[Rb,#imm5*4] and STRB/LDRB Rd,[Rb,#imm5].
   285	fn load_store_immediate_offset(cpu: &mut Cpu, bus: &mut Bus, opcode: u32) -> u32 {
   286	    let offset_field = (opcode >> 6) & 0x1F;
   287	    let (transfer, offset) = match (opcode >> 11) & 3 {
   288	        0 => (Transfer::StoreWord, offset_field << 2),
   289	        1 => (Transfer::LoadWord, offset_field << 2),
   290	        2 => (Transfer::StoreByte, offset_field),
   291	        _ => (Transfer::LoadByte, offset_field),
   292	    };
   293	    let address = cpu.registers[low_register(opcode, 3)].wrapping_add(offset);
   294	    transfer_single(cpu, bus, transfer, low_register(opcode, 0), address)
   295	}
   296	
   297	/// THUMB.10: STRH/LDRH Rd,[Rb,#imm5*2].
   298	fn load_store_halfword(cpu: &mut Cpu, bus: &mut Bus, opcode: u32) -> u32 {
   299	    let transfer = if opcode & (1 << 11) != 0 { Transfer::LoadHalfword } else { Transfer::StoreHalfword };
   300	    let address = cpu.registers[low_register(opcode, 3)].wrapping_add(((opcode >> 6) & 0x1F) << 1);
   301	    transfer_single(cpu, bus, transfer, low_register(opcode, 0), address)
   302	}
   303	
   304	/// THUMB.11: STR/LDR Rd,[SP,#imm8*4].
   305	fn load_store_sp_relative(cpu: &mut Cpu, bus: &mut Bus, opcode: u32) -> u32 {
   306	    let transfer = if opcode & (1 << 11) != 0 { Transfer::LoadWord } else { Transfer::StoreWord };
   307	    let address = cpu.registers[STACK_POINTER].wrapping_add((opcode & 0xFF) << 2);
   308	    transfer_single(cpu, bus, transfer, low_register(opcode, 8), address)
   309	}
   310	
   311	/// THUMB.12: ADD Rd,PC,#imm8*4 (PC word-aligned) and ADD Rd,SP,#imm8*4.
   312	fn load_address(cpu: &mut Cpu, opcode: u32) -> u32 {
   313	    let base = if opcode & (1 << 11) != 0 { cpu.registers[STACK_POINTER] } else { word_aligned_pc(cpu) };
   314	    cpu.registers[low_register(opcode, 8)] = base.wrapping_add((opcode & 0xFF) << 2);
   315	    0
   316	}
   317	
   318	/// THUMB.13: ADD SP,#+/-imm7*4.
   319	fn adjust_stack_pointer(cpu: &mut Cpu, opcode: u32) -> u32 {
   320	    let offset = (opcode & 0x7F) << 2;
   321	    let stack_pointer = cpu.registers[STACK_POINTER];
   322	    cpu.registers[STACK_POINTER] =
   323	        if opcode & 0x80 != 0 { stack_pointer.wrapping_sub(offset) } else { stack_pointer.wrapping_add(offset) };
   324	    0
   325	}
   326	
   327	/// Register list as a bit mask of R0-R15: Rlist in bits 0-7 plus the optional LR/PC bit, so
   328	/// ascending bit order puts the extra register last. An empty list transfers R15 alone
   329	/// (gbatek: "Strange Effects on Invalid Rlist's", ARMv4).
   330	fn register_list(opcode: u32, extra_register: Option<usize>) -> u32 {
   331	    let low_registers = opcode & 0xFF;
   332	    match extra_register {
   333	        Some(register) => low_registers | (1 << register),
   334	        None => low_registers,
   335	    }
   336	}
   337	
   338	/// Bytes a register list occupies; an empty list still moves the base by 40h.
   339	fn register_list_size(registers: u32) -> u32 {
   340	    if registers == 0 { 0x40 } else { registers.count_ones() * 4 }
   341	}
   342	
   343	/// Store the listed registers at ascending addresses from `start`; an empty list stores R15
   344	/// as $+6 (guess, see `store_multiple_empty_list_value`).
   345	fn store_registers(cpu: &Cpu, bus: &mut Bus, registers: u32, start: u32) {
   346	    let mut address = start & !3;
   347	    if registers == 0 {
   348	        bus.write32(address, store_multiple_empty_list_value(cpu));
   349	    }
   350	    for register in 0..16 {
   351	        if registers & (1 << register) != 0 {
   352	            bus.write32(address, cpu.registers[register]);
   353	            address = address.wrapping_add(4);
   354	        }
   355	    }
   356	}
   357	
   358	/// Value stored for R15 by an empty-list STM/PUSH. gbatek does not say; guessed as $+6, one
   359	/// prefetch beyond the usual $+4, mirroring ARM's STM storing $+12.
   360	fn store_multiple_empty_list_value(cpu: &Cpu) -> u32 {
   361	    cpu.registers[PROGRAM_COUNTER].wrapping_add(2)
   362	}
   363	
   364	/// Load the listed registers from ascending addresses from `start`; an empty list loads R15.
   365	fn load_registers(cpu: &mut Cpu, bus: &mut Bus, registers: u32, start: u32) {
   366	    let mut address = start & !3;
   367	    if registers == 0 {
   368	        let target = bus.read32(address);
   369	        cpu.branch_to(target);
   370	    }
   371	    for register in 0..16 {
   372	        if registers & (1 << register) != 0 {
   373	            let value = bus.read32(address);
   374	            cpu.write_register(register, value);
   375	            address = address.wrapping_add(4);
   376	        }
   377	    }
   378	}
   379	
   380	/// THUMB.14: PUSH {Rlist,LR} (STMDB SP!) and POP {Rlist,PC} (LDMIA SP!). POP PC stays in THUMB.
   381	fn push_pop(cpu: &mut Cpu, bus: &mut Bus, opcode: u32) -> u32 {
   382	    let is_pop = opcode & (1 << 11) != 0;
   383	    let with_extra = opcode & (1 << 8) != 0;
   384	    let stack_pointer = cpu.registers[STACK_POINTER];
   385	    if is_pop {
   386	        let registers = register_list(opcode, with_extra.then_some(PROGRAM_COUNTER));
   387	        load_registers(cpu, bus, registers, stack_pointer);
   388	        cpu.registers[STACK_POINTER] = stack_pointer.wrapping_add(register_list_size(registers));
   389	        1
   390	    } else {
   391	        let registers = register_list(opcode, with_extra.then_some(LINK_REGISTER));
   392	        let start = stack_pointer.wrapping_sub(register_list_size(registers));
   393	        store_registers(cpu, bus, registers, start);
   394	        cpu.registers[STACK_POINTER] = start;
   395	        0
   396	    }
   397	}
   398	
   399	/// THUMB.15: STMIA/LDMIA Rb!,{Rlist}, with the ARMv4 base-in-list rules.
   400	fn load_store_multiple(cpu: &mut Cpu, bus: &mut Bus, opcode: u32) -> u32 {
   401	    let base_register = low_register(opcode, 8);
   402	    let base = cpu.registers[base_register];
   403	    let registers = register_list(opcode, None);
   404	    let base_in_list = registers & (1 << base_register) != 0;
   405	    let final_base = base.wrapping_add(register_list_size(registers));
   406	    if opcode & (1 << 11) != 0 {
   407	        load_registers(cpu, bus, registers, base);
   408	        if !base_in_list {
   409	            cpu.registers[base_register] = final_base;
   410	        }
   411	        1
   412	    } else {
   413	        // Rb stores its old value only when it is the lowest (first) register of the list.
   414	        let base_is_first = registers.trailing_zeros() as usize == base_register;
   415	        if base_in_list && !base_is_first {
   416	            cpu.registers[base_register] = final_base;
   417	        }
   418	        store_registers(cpu, bus, registers, base);
   419	        cpu.registers[base_register] = final_base;
   420	        0
   421	    }
   422	}
