   424	/// THUMB.16 (Bcond, condition E undefined) and THUMB.17 (SWI, condition F).
   425	fn conditional_branch_or_swi(cpu: &mut Cpu, opcode: u32) -> u32 {
   426	    let condition = (opcode >> 8) & 0xF;
   427	    match condition {
   428	        0xE => undefined(cpu),
   429	        0xF => {
   430	            cpu.enter_exception(Exception::SoftwareInterrupt);
   431	            0
   432	        }
   433	        _ => {
   434	            if cpu.cond_passed(condition) {
   435	                let offset = (opcode as u8 as i8 as i32 as u32) << 1;
   436	                cpu.branch_to(cpu.registers[PROGRAM_COUNTER].wrapping_add(offset));
   437	            }
   438	            0
   439	        }
   440	    }
   441	}
   442	
   443	/// Sign-extend the low 11 bits of `opcode`.
   444	fn signed_offset_11(opcode: u32) -> u32 {
   445	    (((opcode << 21) as i32) >> 21) as u32
   446	}
   447	
   448	/// THUMB.18: B label.
   449	fn unconditional_branch(cpu: &mut Cpu, opcode: u32) -> u32 {
   450	    cpu.branch_to(cpu.registers[PROGRAM_COUNTER].wrapping_add(signed_offset_11(opcode) << 1));
   451	    0
   452	}
   453	
   454	/// THUMB.19 first half: LR = PC + (signed nn << 12).
   455	fn long_branch_first_half(cpu: &mut Cpu, opcode: u32) -> u32 {
   456	    cpu.registers[LINK_REGISTER] = cpu.registers[PROGRAM_COUNTER].wrapping_add(signed_offset_11(opcode) << 12);
   457	    0
   458	}
   459	
   460	/// THUMB.19 second half: PC = LR + (nn << 1), LR = next instruction | 1.
   461	fn long_branch_second_half(cpu: &mut Cpu, opcode: u32) -> u32 {
   462	    let target = cpu.registers[LINK_REGISTER].wrapping_add((opcode & 0x7FF) << 1);
   463	    let return_address = cpu.current_instruction_address().wrapping_add(2);
   464	    cpu.registers[LINK_REGISTER] = return_address | 1;
   465	    cpu.branch_to(target);
   466	    0
   467	}
