   518	        run(&mut cpu, &mut bus, 1);
   519	        assert_eq!(cpu.registers[2], 0);
   520	        assert!(cpu.zero() && cpu.carry());
   521	    }
   522	
   523	    #[test]
   524	    fn alu_operations() {
   525	        let (mut cpu, mut bus) = setup(&[0x4248, 0x4351, 0x41CA]); // NEG R0,R1 ; MUL R1,R2 ; ROR R2,R1
   526	        cpu.registers[1] = 5;
   527	        cpu.registers[2] = 0x8000_0001;
   528	        run(&mut cpu, &mut bus, 1);
   529	        assert_eq!(cpu.registers[0], (-5i32) as u32);
   530	        assert!(!cpu.carry(), "0 - 5 borrows");
   531	        run(&mut cpu, &mut bus, 1);
   532	        assert_eq!(cpu.registers[1], 0x8000_0005);
   533	        cpu.registers[1] = 36; // ROR by 36 = ROR by 4
   534	        run(&mut cpu, &mut bus, 1);
   535	        assert_eq!(cpu.registers[2], 0x1800_0000);
   536	        assert!(!cpu.carry());
   537	    }
   538	
   539	    #[test]
   540	    fn hi_register_ops_and_bx() {
   541	        // MOV R8,R0 ; ADD R0,R8 ; BX R1
   542	        let (mut cpu, mut bus) = setup(&[0x4680, 0x4440, 0x4708]);
   543	        cpu.registers[0] = 3;
   544	        cpu.registers[1] = 0x0800_0100; // ARM target
   545	        run(&mut cpu, &mut bus, 3);
   546	        assert_eq!(cpu.registers[8], 3);
   547	        assert_eq!(cpu.registers[0], 6);
   548	        assert!(!cpu.in_thumb_state());
   549	        assert_eq!(cpu.registers[PROGRAM_COUNTER], 0x0800_0100);
   550	    }
   551	
   552	    #[test]
   553	    fn mov_pc_and_add_pc_value() {
   554	        // NOP ; MOV R0,PC (reads $+4 = CODE+6) ; MOV PC,R0
   555	        let (mut cpu, mut bus) = setup(&[0x46C0, 0x4678, 0x4687]);
   556	        run(&mut cpu, &mut bus, 2);
   557	        assert_eq!(cpu.registers[0], CODE + 6);
   558	        run(&mut cpu, &mut bus, 1);
   559	        assert!(cpu.in_thumb_state());
   560	        assert_eq!(cpu.registers[PROGRAM_COUNTER], CODE + 6);
   561	    }
   562	
   563	    #[test]
   564	    fn pc_relative_load_and_address_align_pc() {
   565	        // NOP ; LDR R0,[PC,#4] ; ADD R1,PC,#4 ; ...data at CODE+8
   566	        let (mut cpu, mut bus) = setup(&[0x46C0, 0x4801, 0xA101, 0x0000, 0x5678, 0x1234]);
   567	        run(&mut cpu, &mut bus, 3);
   568	        // At CODE+2: PC = CODE+6, aligned to CODE+4, +4 = CODE+8.
   569	        assert_eq!(cpu.registers[0], 0x1234_5678);
   570	        // At CODE+4: PC = CODE+8, +4 = CODE+12.
   571	        assert_eq!(cpu.registers[1], CODE + 12);
   572	    }
   573	
   574	    #[test]
   575	    fn misaligned_loads() {
   576	        // LDR R0,[R4,#0] ; LDRH R1,[R4,#0] ; LDSH R2,[R4,R5]
   577	        let (mut cpu, mut bus) = setup(&[0x6820, 0x8821, 0x5F62]);
   578	        bus.write32(0x0300_1000, 0x8899_AABB);
   579	        cpu.registers[4] = 0x0300_1001;
   580	        cpu.registers[5] = 0;
   581	        run(&mut cpu, &mut bus, 3);
   582	        assert_eq!(cpu.registers[0], 0xBB88_99AA);
   583	        assert_eq!(cpu.registers[1], 0xBB00_00AA);
   584	        assert_eq!(cpu.registers[2], 0xFFFF_FFAA, "odd LDSH acts as LDSB");
   585	    }
   586	
   587	    #[test]
   588	    fn push_pop_round_trip() {
   589	        // PUSH {R0,R1,LR} ; POP {R2,R3,PC}
   590	        let (mut cpu, mut bus) = setup(&[0xB503, 0xBD0C]);
   591	        cpu.registers[0] = 10;
   592	        cpu.registers[1] = 20;
   593	        cpu.registers[LINK_REGISTER] = 0x0300_0101;
   594	        run(&mut cpu, &mut bus, 1);
   595	        assert_eq!(cpu.registers[STACK_POINTER], 0x0300_7EF4);
   596	        assert_eq!(bus.read32(0x0300_7EFC), 0x0300_0101);
   597	        run(&mut cpu, &mut bus, 1);
   598	        assert_eq!((cpu.registers[2], cpu.registers[3]), (10, 20));
   599	        assert_eq!(cpu.registers[STACK_POINTER], 0x0300_7F00);
   600	        assert_eq!(cpu.registers[PROGRAM_COUNTER], 0x0300_0100);
   601	        assert!(cpu.in_thumb_state());
   602	    }
   603	
   604	    #[test]
   605	    fn stmia_and_ldmia_base_in_list() {
   606	        // STMIA R0!,{R0,R1} (old base) ; STMIA R1!,{R0,R1} (new base) ; LDMIA R2!,{R1,R2}
   607	        let (mut cpu, mut bus) = setup(&[0xC003, 0xC103, 0xCA06]);
   608	        cpu.registers[0] = 0x0300_1000;
   609	        cpu.registers[1] = 0x0300_2000;
   610	        run(&mut cpu, &mut bus, 1);
   611	        assert_eq!(bus.read32(0x0300_1000), 0x0300_1000);
   612	        assert_eq!(cpu.registers[0], 0x0300_1008);
   613	        run(&mut cpu, &mut bus, 1);
