1	//! THUMB (16-bit) instruction decode and execute (gbatek: THUMB Instruction Summary and THUMB Opcodes).
2	//!
3	//! Every handler returns internal (I) cycles only; the bus counts its own S/N access cycles
4	//! (gbatek: ARM CPU Instruction Cycle Times). R15 reads as the opcode's address + 4.
5	
6	use super::alu::{self, ShiftType};
7	use super::{Cpu, Exception, LINK_REGISTER, PROGRAM_COUNTER, STACK_POINTER};
8	use crate::bus::Bus;
9	
10	/// Execute one THUMB opcode and return its internal cycles.
11	pub(super) fn execute_thumb(cpu: &mut Cpu, bus: &mut Bus, opcode: u16) -> u32 {
12	    let opcode = opcode as u32;
13	    match opcode >> 11 {
14	        0b00000..=0b00010 => move_shifted_register(cpu, opcode),
15	        0b00011 => add_subtract(cpu, opcode),
16	        0b00100..=0b00111 => immediate_operation(cpu, opcode),
17	        0b01000 if opcode & 0x0400 == 0 => alu_operation(cpu, opcode),
18	        0b01000 => hi_register_operation(cpu, opcode),
19	        0b01001 => load_pc_relative(cpu, bus, opcode),
20	        0b01010 | 0b01011 if opcode & 0x0200 == 0 => load_store_register_offset(cpu, bus, opcode),
21	        0b01010 | 0b01011 => load_store_sign_extended(cpu, bus, opcode),
22	        0b01100..=0b01111 => load_store_immediate_offset(cpu, bus, opcode),
23	        0b10000 | 0b10001 => load_store_halfword(cpu, bus, opcode),
24	        0b10010 | 0b10011 => load_store_sp_relative(cpu, bus, opcode),
25	        0b10100 | 0b10101 => load_address(cpu, opcode),
26	        0b10110 if opcode & 0x0F00 == 0 => adjust_stack_pointer(cpu, opcode),
27	        0b10110 | 0b10111 if opcode & 0x0600 == 0x0400 => push_pop(cpu, bus, opcode),
28	        0b11000 | 0b11001 => load_store_multiple(cpu, bus, opcode),
29	        0b11010 | 0b11011 => conditional_branch_or_swi(cpu, opcode),
30	        0b11100 => unconditional_branch(cpu, opcode),
31	        0b11110 => long_branch_first_half(cpu, opcode),
32	        0b11111 => long_branch_second_half(cpu, opcode),
33	        // BKPT, BLX and other ARMv5 encodings do not exist on the ARMv4T.
34	        _ => undefined(cpu),
35	    }
36	}
37	
38	/// Low register number (R0-R7) from the 3-bit field at `shift`.
39	fn low_register(opcode: u32, shift: u32) -> usize {
40	    ((opcode >> shift) & 7) as usize
41	}
42	
43	/// Raise the Undefined Instruction exception for encodings the ARMv4T lacks
44	/// (gbatek: ARM CPU Exceptions).
45	fn undefined(cpu: &mut Cpu) -> u32 {
46	    cpu.enter_exception(Exception::UndefinedInstruction);
47	    0
48	}
49	
50	/// THUMB.1: LSL/LSR/ASR Rd,Rs,#offset (gbatek: THUMB Opcodes: Register Operations).
51	fn move_shifted_register(cpu: &mut Cpu, opcode: u32) -> u32 {
52	    let shift_type = ShiftType::from_bits(opcode >> 11);
53	    let shift_amount = (opcode >> 6) & 0x1F;
54	    let source = cpu.registers[low_register(opcode, 3)];
55	    let (result, carry) = alu::shift_by_immediate(shift_type, source, shift_amount, cpu.carry());
56	    cpu.registers[low_register(opcode, 0)] = result;
57	    cpu.set_logical_flags(result, carry);
58	    0
59	}
60	
61	/// THUMB.2: ADD/SUB Rd,Rs,Rn and ADD/SUB Rd,Rs,#imm3.
62	fn add_subtract(cpu: &mut Cpu, opcode: u32) -> u32 {
63	    let operand_field = (opcode >> 6) & 7;
64	    let is_immediate = opcode & (1 << 10) != 0;
65	    let is_subtract = opcode & (1 << 9) != 0;
66	    let operand = if is_immediate { operand_field } else { cpu.registers[operand_field as usize] };
67	    let source = cpu.registers[low_register(opcode, 3)];
68	    let result = if is_subtract { alu::subtract(source, operand) } else { alu::add(source, operand) };
69	    cpu.registers[low_register(opcode, 0)] = result.value;
70	    cpu.set_arithmetic_flags(result);
71	    0
72	}
73	
74	/// THUMB.3: MOV/CMP/ADD/SUB Rd,#imm8.
75	fn immediate_operation(cpu: &mut Cpu, opcode: u32) -> u32 {
76	    let destination = low_register(opcode, 8);
77	    let immediate = opcode & 0xFF;
78	    let current = cpu.registers[destination];
79	    match (opcode >> 11) & 3 {
80	        0 => {
81	            cpu.registers[destination] = immediate;
82	            cpu.set_negative_and_zero(immediate);
83	        }
84	        1 => cpu.set_arithmetic_flags(alu::subtract(current, immediate)),
85	        2 => {
86	            let result = alu::add(current, immediate);
87	            cpu.registers[destination] = result.value;
88	            cpu.set_arithmetic_flags(result);
89	        }
90	        _ => {
91	            let result = alu::subtract(current, immediate);
92	            cpu.registers[destination] = result.value;
93	            cpu.set_arithmetic_flags(result);
94	        }
95	    }
96	    0
97	}
98	
99	/// THUMB.4: the 16 two-register ALU operations.
100	fn alu_operation(cpu: &mut Cpu, opcode: u32) -> u32 {
101	    let destination = low_register(opcode, 0);
102	    let first = cpu.registers[destination];
103	    let second = cpu.registers[low_register(opcode, 3)];
104	    let carry_in = cpu.carry();
105	    match (opcode >> 6) & 0xF {
106	        0x0 => write_logical(cpu, destination, first & second),
107	        0x1 => write_logical(cpu, destination, first ^ second),
108	        0x2 => shift_by_register(cpu, destination, ShiftType::LogicalLeft, second),
109	        0x3 => shift_by_register(cpu, destination, ShiftType::LogicalRight, second),
110	        0x4 => shift_by_register(cpu, destination, ShiftType::ArithmeticRight, second),
111	        0x5 => write_arithmetic(cpu, destination, alu::add_with_carry(first, second, carry_in)),
112	        0x6 => write_arithmetic(cpu, destination, alu::subtract_with_carry(first, second, carry_in)),
113	        0x7 => shift_by_register(cpu, destination, ShiftType::RotateRight, second),
114	        0x8 => {
115	            cpu.set_negative_and_zero(first & second);
116	            0
117	        }
118	        0x9 => write_arithmetic(cpu, destination, alu::subtract(0, second)),
119	        0xA => {
120	            cpu.set_arithmetic_flags(alu::subtract(first, second));
121	            0
122	        }
123	        0xB => {
124	            cpu.set_arithmetic_flags(alu::add(first, second));
125	            0
126	        }
127	        0xC => write_logical(cpu, destination, first | second),
128	        // ponytail: ARMv4 "destroys" C on MUL; we leave it unchanged (gbatek gives no value).
129	        0xD => write_logical(cpu, destination, first.wrapping_mul(second)) + multiply_cycles(first),
130	        0xE => write_logical(cpu, destination, first & !second),
131	        _ => write_logical(cpu, destination, !second),
132	    }
133	}
134	
135	/// THUMB.4 logical result: Rd = result, N and Z set, C and V unchanged. No internal cycles.
136	fn write_logical(cpu: &mut Cpu, destination: usize, result: u32) -> u32 {
137	    cpu.registers[destination] = result;
138	    cpu.set_negative_and_zero(result);
139	    0
140	}
141	
142	/// THUMB.4 arithmetic result: Rd = result, N, Z, C and V set. No internal cycles.
143	fn write_arithmetic(cpu: &mut Cpu, destination: usize, result: alu::ArithmeticResult) -> u32 {
144	    cpu.registers[destination] = result.value;
145	    cpu.set_arithmetic_flags(result);
146	    0
147	}
148	
149	/// THUMB.4 LSL/LSR/ASR/ROR Rd,Rs: shift Rd by the low byte of Rs, N/Z/C set. Costs 1I.
150	fn shift_by_register(cpu: &mut Cpu, destination: usize, shift_type: ShiftType, amount_register: u32) -> u32 {
151	    let (result, carry) =
152	        alu::shift_by_register(shift_type, cpu.registers[destination], amount_register, cpu.carry());
153	    cpu.registers[destination] = result;
154	    cpu.set_logical_flags(result, carry);
155	    1
156	}
157	
158	/// Internal cycles m of MUL from the multiplier's top bytes being all zero or all one
159	/// (gbatek: ARM Opcodes: Multiply; THUMB.4 uses the incoming Rd value).
160	fn multiply_cycles(multiplier: u32) -> u32 {
161	    let top_bits_uniform = |mask: u32| multiplier & mask == 0 || multiplier & mask == mask;
162	    if top_bits_uniform(0xFFFF_FF00) {
163	        1
164	    } else if top_bits_uniform(0xFFFF_0000) {
165	        2
166	    } else if top_bits_uniform(0xFF00_0000) {
167	        3
168	    } else {
169	        4
170	    }
171	}
172	
173	/// THUMB.5: ADD/CMP/MOV with R0-R15 and BX.
174	fn hi_register_operation(cpu: &mut Cpu, opcode: u32) -> u32 {
175	    let destination = low_register(opcode, 0) | (((opcode >> 7) & 1) << 3) as usize;
176	    let source = ((opcode >> 3) & 0xF) as usize;
177	    let source_value = cpu.registers[source];
178	    match (opcode >> 8) & 3 {
179	        0 => cpu.write_register(destination, cpu.registers[destination].wrapping_add(source_value)),
180	        1 => cpu.set_arithmetic_flags(alu::subtract(cpu.registers[destination], source_value)),
181	        2 => cpu.write_register(destination, source_value),
182	        _ => {
183	            // ponytail: MSBd set (ARMv5 BLX) is treated as plain BX on the ARMv4T.
184	            cpu.set_thumb_state(source_value & 1 != 0);
185	            cpu.branch_to(source_value);
186	        }
187	    }
188	    0
189	}
190	
191	/// PC as a base for PC-relative addressing: ($+4) AND NOT 2.
192	fn word_aligned_pc(cpu: &Cpu) -> u32 {
193	    cpu.registers[PROGRAM_COUNTER] & !3
194	}
195	
196	/// THUMB.6: LDR Rd,[PC,#imm8*4].
197	fn load_pc_relative(cpu: &mut Cpu, bus: &mut Bus, opcode: u32) -> u32 {
198	    let address = word_aligned_pc(cpu).wrapping_add((opcode & 0xFF) << 2);
199	    cpu.registers[low_register(opcode, 8)] = bus.read32(address);
200	    1
201	}
202	
203	/// Word load with the misaligned rotation (gbatek: ARM CPU Memory Alignments, "rotated read").
204	fn load_word_rotated(bus: &mut Bus, address: u32) -> u32 {
205	    bus.read32(address).rotate_right((address & 3) * 8)
206	}
207	
208	/// LDRH; an odd address reads the aligned halfword rotated by 8 (ARMv4 behaviour).
209	fn load_halfword_unsigned(bus: &mut Bus, address: u32) -> u32 {
210	    (bus.read16(address) as u32).rotate_right((address & 1) * 8)
211	}
212	
213	/// LDSH; an odd address acts as LDSB on that byte (ARMv4 behaviour).
214	fn load_halfword_signed(bus: &mut Bus, address: u32) -> u32 {
215	    if address & 1 != 0 {
216	        load_byte_signed(bus, address)
217	    } else {
218	        bus.read16(address) as i16 as i32 as u32
219	    }
220	}
221	
222	fn load_byte_signed(bus: &mut Bus, address: u32) -> u32 {
223	    bus.read8(address) as i8 as i32 as u32
224	}
225	
226	/// The data sizes of THUMB.7 to THUMB.11, decoded per format.
227	#[derive(Clone, Copy)]
228	enum Transfer {
229	    StoreWord,
230	    StoreHalfword,
231	    StoreByte,
232	    LoadWord,
233	    LoadHalfword,
234	    LoadByte,
235	    LoadSignedHalfword,
236	    LoadSignedByte,
237	}
238	
239	/// Perform a single load or store of register Rd at `address`; returns internal cycles
240	/// (1I for loads, none for stores).
241	fn transfer_single(cpu: &mut Cpu, bus: &mut Bus, transfer: Transfer, register: usize, address: u32) -> u32 {
242	    let value = cpu.registers[register];
243	    match transfer {
244	        Transfer::StoreWord => bus.write32(address & !3, value),
245	        Transfer::StoreHalfword => bus.write16(address & !1, value as u16),
246	        Transfer::StoreByte => bus.write8(address, value as u8),
247	        Transfer::LoadWord => cpu.registers[register] = load_word_rotated(bus, address),
248	        Transfer::LoadHalfword => cpu.registers[register] = load_halfword_unsigned(bus, address),
249	        Transfer::LoadByte => cpu.registers[register] = bus.read8(address) as u32,
250	        Transfer::LoadSignedHalfword => cpu.registers[register] = load_halfword_signed(bus, address),
251	        Transfer::LoadSignedByte => cpu.registers[register] = load_byte_signed(bus, address),
252	    }
253	    match transfer {
254	        Transfer::StoreWord | Transfer::StoreHalfword | Transfer::StoreByte => 0,
255	        _ => 1, // loads spend 1I
256	    }
257	}
258	
259	/// Rb + Ro for THUMB.7 and THUMB.8.
260	fn register_offset_address(cpu: &Cpu, opcode: u32) -> u32 {
261	    cpu.registers[low_register(opcode, 3)].wrapping_add(cpu.registers[low_register(opcode, 6)])
262	}
263	
264	/// THUMB.7: STR/STRB/LDR/LDRB Rd,[Rb,Ro].
265	fn load_store_register_offset(cpu: &mut Cpu, bus: &mut Bus, opcode: u32) -> u32 {
266	    let transfer = [Transfer::StoreWord, Transfer::StoreByte, Transfer::LoadWord, Transfer::LoadByte]
267	        [((opcode >> 10) & 3) as usize];
268	    let address = register_offset_address(cpu, opcode);
269	    transfer_single(cpu, bus, transfer, low_register(opcode, 0), address)
270	}
271	
272	/// THUMB.8: STRH/LDSB/LDRH/LDSH Rd,[Rb,Ro].
273	fn load_store_sign_extended(cpu: &mut Cpu, bus: &mut Bus, opcode: u32) -> u32 {
274	    let transfer = [
275	        Transfer::StoreHalfword,
276	        Transfer::LoadSignedByte,
277	        Transfer::LoadHalfword,
278	        Transfer::LoadSignedHalfword,
279	    ][((opcode >> 10) & 3) as usize];
280	    let address = register_offset_address(cpu, opcode);
281	    transfer_single(cpu, bus, transfer, low_register(opcode, 0), address)
282	}
283	
284	/// THUMB.9: STR/LDR Rd,[Rb,#imm5*4] and STRB/LDRB Rd,[Rb,#imm5].
285	fn load_store_immediate_offset(cpu: &mut Cpu, bus: &mut Bus, opcode: u32) -> u32 {
286	    let offset_field = (opcode >> 6) & 0x1F;
287	    let (transfer, offset) = match (opcode >> 11) & 3 {
288	        0 => (Transfer::StoreWord, offset_field << 2),
289	        1 => (Transfer::LoadWord, offset_field << 2),
290	        2 => (Transfer::StoreByte, offset_field),
291	        _ => (Transfer::LoadByte, offset_field),
292	    };
293	    let address = cpu.registers[low_register(opcode, 3)].wrapping_add(offset);
294	    transfer_single(cpu, bus, transfer, low_register(opcode, 0), address)
295	}
296	
297	/// THUMB.10: STRH/LDRH Rd,[Rb,#imm5*2].
298	fn load_store_halfword(cpu: &mut Cpu, bus: &mut Bus, opcode: u32) -> u32 {
299	    let transfer = if opcode & (1 << 11) != 0 { Transfer::LoadHalfword } else { Transfer::StoreHalfword };
300	    let address = cpu.registers[low_register(opcode, 3)].wrapping_add(((opcode >> 6) & 0x1F) << 1);
301	    transfer_single(cpu, bus, transfer, low_register(opcode, 0), address)
302	}
303	
304	/// THUMB.11: STR/LDR Rd,[SP,#imm8*4].
305	fn load_store_sp_relative(cpu: &mut Cpu, bus: &mut Bus, opcode: u32) -> u32 {
306	    let transfer = if opcode & (1 << 11) != 0 { Transfer::LoadWord } else { Transfer::StoreWord };
307	    let address = cpu.registers[STACK_POINTER].wrapping_add((opcode & 0xFF) << 2);
308	    transfer_single(cpu, bus, transfer, low_register(opcode, 8), address)
309	}
310	
311	/// THUMB.12: ADD Rd,PC,#imm8*4 (PC word-aligned) and ADD Rd,SP,#imm8*4.
312	fn load_address(cpu: &mut Cpu, opcode: u32) -> u32 {
313	    let base = if opcode & (1 << 11) != 0 { cpu.registers[STACK_POINTER] } else { word_aligned_pc(cpu) };
314	    cpu.registers[low_register(opcode, 8)] = base.wrapping_add((opcode & 0xFF) << 2);
315	    0
316	}
317	
318	/// THUMB.13: ADD SP,#+/-imm7*4.
319	fn adjust_stack_pointer(cpu: &mut Cpu, opcode: u32) -> u32 {
320	    let offset = (opcode & 0x7F) << 2;
321	    let stack_pointer = cpu.registers[STACK_POINTER];
322	    cpu.registers[STACK_POINTER] =
323	        if opcode & 0x80 != 0 { stack_pointer.wrapping_sub(offset) } else { stack_pointer.wrapping_add(offset) };
324	    0
325	}
326	
327	/// Register list as a bit mask of R0-R15: Rlist in bits 0-7 plus the optional LR/PC bit, so
328	/// ascending bit order puts the extra register last. An empty list transfers R15 alone
329	/// (gbatek: "Strange Effects on Invalid Rlist's", ARMv4).
330	fn register_list(opcode: u32, extra_register: Option<usize>) -> u32 {
331	    let low_registers = opcode & 0xFF;
332	    match extra_register {
333	        Some(register) => low_registers | (1 << register),
334	        None => low_registers,
335	    }
336	}
337	
338	/// Bytes a register list occupies; an empty list still moves the base by 40h.
339	fn register_list_size(registers: u32) -> u32 {
340	    if registers == 0 { 0x40 } else { registers.count_ones() * 4 }
341	}
342	
343	/// Store the listed registers at ascending addresses from `start`; an empty list stores R15
344	/// as $+6 (guess, see `store_multiple_empty_list_value`).
345	fn store_registers(cpu: &Cpu, bus: &mut Bus, registers: u32, start: u32) {
346	    let mut address = start & !3;
347	    if registers == 0 {
348	        bus.write32(address, store_multiple_empty_list_value(cpu));
349	    }
350	    for register in 0..16 {
351	        if registers & (1 << register) != 0 {
352	            bus.write32(address, cpu.registers[register]);
353	            address = address.wrapping_add(4);
354	        }
355	    }
356	}
357	
358	/// Value stored for R15 by an empty-list STM/PUSH. gbatek does not say; guessed as $+6, one
359	/// prefetch beyond the usual $+4, mirroring ARM's STM storing $+12.
360	fn store_multiple_empty_list_value(cpu: &Cpu) -> u32 {
361	    cpu.registers[PROGRAM_COUNTER].wrapping_add(2)
362	}
363	
364	/// Load the listed registers from ascending addresses from `start`; an empty list loads R15.
365	fn load_registers(cpu: &mut Cpu, bus: &mut Bus, registers: u32, start: u32) {
366	    let mut address = start & !3;
367	    if registers == 0 {
368	        let target = bus.read32(address);
369	        cpu.branch_to(target);
370	    }
371	    for register in 0..16 {
372	        if registers & (1 << register) != 0 {
373	            let value = bus.read32(address);
374	            cpu.write_register(register, value);
375	            address = address.wrapping_add(4);
376	        }
377	    }
378	}
379	
380	/// THUMB.14: PUSH {Rlist,LR} (STMDB SP!) and POP {Rlist,PC} (LDMIA SP!). POP PC stays in THUMB.
381	fn push_pop(cpu: &mut Cpu, bus: &mut Bus, opcode: u32) -> u32 {
382	    let is_pop = opcode & (1 << 11) != 0;
383	    let with_extra = opcode & (1 << 8) != 0;
384	    let stack_pointer = cpu.registers[STACK_POINTER];
385	    if is_pop {
386	        let registers = register_list(opcode, with_extra.then_some(PROGRAM_COUNTER));
387	        load_registers(cpu, bus, registers, stack_pointer);
388	        cpu.registers[STACK_POINTER] = stack_pointer.wrapping_add(register_list_size(registers));
389	        1
390	    } else {
391	        let registers = register_list(opcode, with_extra.then_some(LINK_REGISTER));
392	        let start = stack_pointer.wrapping_sub(register_list_size(registers));
393	        store_registers(cpu, bus, registers, start);
394	        cpu.registers[STACK_POINTER] = start;
395	        0
396	    }
397	}
398	
399	/// THUMB.15: STMIA/LDMIA Rb!,{Rlist}, with the ARMv4 base-in-list rules.
400	fn load_store_multiple(cpu: &mut Cpu, bus: &mut Bus, opcode: u32) -> u32 {
401	    let base_register = low_register(opcode, 8);
402	    let base = cpu.registers[base_register];
403	    let registers = register_list(opcode, None);
404	    let base_in_list = registers & (1 << base_register) != 0;
405	    let final_base = base.wrapping_add(register_list_size(registers));
406	    if opcode & (1 << 11) != 0 {
407	        load_registers(cpu, bus, registers, base);
408	        if !base_in_list {
409	            cpu.registers[base_register] = final_base;
410	        }
411	        1
412	    } else {
413	        // Rb stores its old value only when it is the lowest (first) register of the list.
414	        let base_is_first = registers.trailing_zeros() as usize == base_register;
415	        if base_in_list && !base_is_first {
416	            cpu.registers[base_register] = final_base;
417	        }
418	        store_registers(cpu, bus, registers, base);
419	        cpu.registers[base_register] = final_base;
420	        0
421	    }
422	}
423	
424	/// THUMB.16 (Bcond, condition E undefined) and THUMB.17 (SWI, condition F).
425	fn conditional_branch_or_swi(cpu: &mut Cpu, opcode: u32) -> u32 {
426	    let condition = (opcode >> 8) & 0xF;
427	    match condition {
428	        0xE => undefined(cpu),
429	        0xF => {
430	            cpu.enter_exception(Exception::SoftwareInterrupt);
431	            0
432	        }
433	        _ => {
434	            if cpu.cond_passed(condition) {
435	                let offset = (opcode as u8 as i8 as i32 as u32) << 1;
436	                cpu.branch_to(cpu.registers[PROGRAM_COUNTER].wrapping_add(offset));
437	            }
438	            0
439	        }
440	    }
441	}
442	
443	/// Sign-extend the low 11 bits of `opcode`.
444	fn signed_offset_11(opcode: u32) -> u32 {
445	    (((opcode << 21) as i32) >> 21) as u32
446	}
447	
448	/// THUMB.18: B label.
449	fn unconditional_branch(cpu: &mut Cpu, opcode: u32) -> u32 {
450	    cpu.branch_to(cpu.registers[PROGRAM_COUNTER].wrapping_add(signed_offset_11(opcode) << 1));
451	    0
452	}
453	
454	/// THUMB.19 first half: LR = PC + (signed nn << 12).
455	fn long_branch_first_half(cpu: &mut Cpu, opcode: u32) -> u32 {
456	    cpu.registers[LINK_REGISTER] = cpu.registers[PROGRAM_COUNTER].wrapping_add(signed_offset_11(opcode) << 12);
457	    0
458	}
459	
460	/// THUMB.19 second half: PC = LR + (nn << 1), LR = next instruction | 1.
461	fn long_branch_second_half(cpu: &mut Cpu, opcode: u32) -> u32 {
462	    let target = cpu.registers[LINK_REGISTER].wrapping_add((opcode & 0x7FF) << 1);
463	    let return_address = cpu.current_instruction_address().wrapping_add(2);
464	    cpu.registers[LINK_REGISTER] = return_address | 1;
465	    cpu.branch_to(target);
466	    0
467	}
